// #463316 (9e970625b0b90fee67463316) «iOS - מסך «היסטוריית תפילות שלי»: הכותרת העליונה שונה משאר המסכים ומ-Figma» — עבר QA 21.10.2026.
// מה רצוי: «לפי Figma S-26 (454:5725) הכותרת של מסך ההיסטוריה זהה לשאר המסכים: חץ חזרה בלי עיגול, כותרת גדולה ומודגשת וקו מתחת לכותרת.»
// Имя экрана — по документации S-26 «היסטוריית התפילות שלי» (коммент программиста dd3c61e). Факт 21.10: стрелка без круга, жирный
// заголовок, линия; поиск «מנחה» 4/4, пустой поиск — сообщение; «→» назад на главную (2110-9e970625-history.png).
// Автоматически: размеры заголовка и «חזרה» = экрану «תפילות» (±2 pt; 19.10 было 24 vs 33 и 40×40 vs 36×37), текст заголовка,
// поиск, назад. Жирность и линия — по скрину (@manual-check). Нужно 4+ молитв (иначе нет «צפה בהכל»). Кейс: .qa/tests/prayer-history/PH-03-history-header.md.
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, byLabel } from '../../helpers/ui.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';
import { goHome, counter, openCatalog, nodes, headerTap } from '../_lib/readiness-1910.ts';
import { HISTORY_TITLE, openHistoryFromHome, headerNodes, typeInto, saveShot } from '../_lib/app-2110.ts';

const ROW_RE = /^(שחרית|מנחה|ערבית|[א-ת ]+), (.+), \d{2}:\d{2}(:\d{2})?$/;
const rows = async () => (await nodes()).filter((n) => ROW_RE.test(n.label) && n.visible).map((n) => n.label);

describe('21.10 — шапка «היסטוריית התפילות שלי» (#463316)', () => {
  afterEach(async () => { await goHome().catch(() => {}); });

  it('PH-03 Шапка истории как у «תפילות»: заголовок «היסטוריית התפילות שלי» той же высоты, «חזרה» того же размера (без круга); поиск «מנחה» фильтрует, пустой поиск — сообщение; «חזרה» → главная #463316 #9e970625 S-26 AC4 @prod-safe @manual-check', async function () {
    await goHome();
    if ((await counter('סה״כ תפילות')) <= 3) skipWith(this, 'нужно 4+ молитв для «צפה בהכל»');

    await openCatalog();
    const cat = await headerNodes('תפילות');
    await openHistoryFromHome();
    const his = await headerNodes(HISTORY_TITLE);
    console.log(`[PH-03] «תפילות» h=${cat.t?.h} back=${cat.back?.w}x${cat.back?.h}; история h=${his.t?.h} back=${his.back?.w}x${his.back?.h}`);
    expect(cat.t && cat.back && his.t && his.back).toBeTruthy();
    expect(Math.abs(his.t!.h - cat.t!.h)).toBeLessThanOrEqual(2);
    expect(Math.abs(his.back!.w - cat.back!.w)).toBeLessThanOrEqual(2);
    expect(Math.abs(his.back!.h - cat.back!.h)).toBeLessThanOrEqual(2);
    expect(await shown(byText('היסטוריית תפילות שלי'))).toBe(false);   // старое имя
    console.log(`[PH-03] скрин шапки (жирность, линия под шапкой — сверить с Figma 454:5725): ${await saveShot('PH-03-history-header.png')}`);

    // Поиск по типу и пустой результат (S-26 AC4).
    const search = (await byLabel('חיפוש')) as unknown as WebdriverIO.Element;
    await typeInto(search, 'מנחה');
    await driver.waitUntil(async () => { const r = await rows(); return r.length > 0 && r.every((x) => x.startsWith('מנחה, ')); },
      { timeout: 15000, timeoutMsg: 'поиск «מנחה» не отфильтровал историю' });
    await typeInto(search, 'zzzqq');
    await expect(byTextContains('לא נמצאו תפילות')).toBeExisting({ wait: 15000 });
    expect((await rows()).length).toBe(0);
    await typeInto(search, '');

    // «חזרה» (стрелка справа) → главная.
    await headerTap('חזרה');
    await expect(byTextContains('תפילות היום')).toBeExisting({ wait: 20000 });
  });
});
